fun main() {
    val input = System.`in`.bufferedReader().readText().filter { it !in " \n\r\t" }
    val chars = input.take(16).toList()
    val board = Array(4) { IntArray(4) }
    for (i in 0..3) {
        for (j in 0..3) {
            val c = chars[i * 4 + j]
            board[i][j] = when (c) {
                'x' -> 1
                'o' -> -3
                else -> 0
            }
        }
    }
    var canWin = false
    outer@ for (i in 0..3) {
        for (j in 0..3) {
            if (board[i][j] >= 0) {
                var sumHor = 0
                var sumVer = 0
                var sumDiaUp = 0
                var sumDiaDown = 0
                if (j < 2) {
                    sumHor = board[i][j] + board[i][j + 1] + board[i][j + 2]
                }
                if (i < 2) {
                    sumVer = board[i][j] + board[i + 1][j] + board[i + 2][j]
                }
                if (i < 2 && j < 2) {
                    sumDiaUp = board[i][j] + board[i + 1][j + 1] + board[i + 2][j + 2]
                }
                if (i >= 2 && j < 2) {
                    sumDiaDown = board[i][j] + board[i - 1][j + 1] + board[i - 2][j + 2]
                }
                if (sumHor == 2 || sumVer == 2 || sumDiaUp == 2 || sumDiaDown == 2) {
                    canWin = true
                    break@outer
                }
            }
        }
    }
    println(if (canWin) "YES" else "NO")
